  // Settings -> Voice -> the recognition picker, which sits directly above the synthesis one. It is
  // translated for the same reason and to the same depth: half a section in Russian under a heading
  // in English is the state this table exists to end.
  "stt.title": { en: "Speech recognition", ru: "Распознавание речи" },
  "stt.intro": {
    en: "A model that runs here, on this machine's processor, with no endpoint and no key. Pick one, download it, and the voice page listens with it instead of the browser. Which of the installed ones transcribes voice notes is chosen in the card above. Nothing is downloaded until you ask for it, and deleting one puts the disk back.",
    ru: "Модель, которая работает здесь, на процессоре этой машины, без адреса и без ключа. Выберите одну, скачайте — и голосовая страница будет слушать ею, а не браузером. Какая из установленных расшифровывает голосовые заметки, выбирается в карточке выше. Ничего не скачивается, пока вы не попросите, а удаление возвращает место на диске.",
  },
  "stt.inuse": { en: "In use", ru: "Используется" },
  "stt.inuse.none": { en: "none — the endpoint or the browser listens", ru: "ничего — слушает сервер или браузер" },
