  "nset.quiet.title": { en: "Quiet hours", ru: "Тихие часы" },
  "nset.quiet.sub": { en: "Inside them nothing below urgent pushes, raises a desktop notification or goes to Telegram. The app's list still gets everything.", ru: "В это время ничего, кроме срочного, не приходит push, на рабочий стол и в Telegram. В списке приложения всё сохраняется." },
