  "nset.mute.always": { en: "Always", ru: "Всегда" },
  "nset.mute.unmute": { en: "Unmute", ru: "Снять" },
  "nset.popups.title": { en: "Inside the app", ru: "Внутри приложения" },
  "nset.popups": { en: "Show pop-ups in the app", ru: "Показывать всплывающие уведомления в приложении" },
  "nset.popups.sub": { en: "New notifications pop up in a corner of the app for a few seconds. Off: they go only to the bell and the inbox. Push, desktop and Telegram notifications are not affected, and each device keeps its own choice.", ru: "Новые уведомления на несколько секунд всплывают в углу приложения. Если выключить, они попадают только под колокольчик и во входящие. Push, уведомления рабочего стола и Telegram это не затрагивает; у каждого устройства свой выбор." },
  "nset.devices.title": { en: "Devices with push", ru: "Устройства с push" },
  "nset.devices.sub": { en: "Every browser and phone that receives push. A device that keeps failing for a week is removed by itself.", ru: "Все браузеры и телефоны, получающие push. Устройство, которое не отвечает неделю, удаляется само." },
