  "bs.none.body": { en: "The agent's browser runs as a service of its own. On a server, add the line below to the .env file and start the stack again; on the desktop, install the browser component.", ru: "Браузер агента работает отдельной службой. На сервере добавьте строку ниже в файл .env и перезапустите стек; на компьютере установите компонент браузера." },
