    en: "The private chat is a window onto one session at a time: /sessions lists them, /use switches. Every other session still speaks there, under its own name.",
    ru: "Личный чат — окно в одну сессию за раз: /sessions показывает список, /use переключает. Остальные сессии тоже пишут туда, каждая под своим именем.",
