  "focus.enable.body": { en: "An orchestrator runs the team: it keeps the brief, hires, hands out tasks, reads the replies and wakes you when it cannot go on without you. It writes no code and runs no command itself.", ru: "Оркестратор ведёт команду: держит бриф, нанимает, раздаёт задачи, читает ответы и будит вас, когда без вас не обойтись. Сам он не пишет код и не запускает команды." },
  "focus.enable.action": { en: "Switch the orchestrator on", ru: "Включить оркестратор" },
