  "focus.enable.autonomy": { en: "Autonomy", ru: "Самостоятельность" },
  "focus.enable.cap": { en: "Staff at once, at most", ru: "Сотрудников одновременно, не больше" },
  "focus.enable.cap.hint": { en: "The orchestrator chooses how many work at once, up to this limit.", ru: "Сколько работает одновременно, оркестратор решает сам, в пределах этого потолка." },
  "focus.enable.cost": { en: "A project with an orchestrator spends roughly fifteen times the tokens of a single chat: every member is a session of its own, and the orchestrator reads the whole project at every turn.", ru: "Проект с оркестратором тратит примерно в пятнадцать раз больше токенов, чем один чат: каждый сотрудник — отдельная сессия, а оркестратор на каждом ходу читает весь проект." },
  "focus.enable.go": { en: "Switch on", ru: "Включить" },
  "focus.enable.done": { en: "The orchestrator is on", ru: "Оркестратор включён" },
