  "cal.steps.google.1": { en: "In Google Cloud, enable the Google Calendar API for a project.", ru: "В Google Cloud включите для проекта Google Calendar API." },
  "cal.steps.google.2": { en: "Create an OAuth client of type “Web application” and add the redirect address below.", ru: "Создайте OAuth-клиент типа «Веб-приложение» и добавьте адрес возврата, указанный ниже." },
  "cal.steps.google.3": { en: "Paste the client ID and secret here, then sign in and allow access to calendar events.", ru: "Вставьте сюда ID и секрет клиента, затем войдите и разрешите доступ к событиям календаря." },
