  "cal.steps.outlook.2": { en: "Add the redirect address below and the delegated permissions Calendars.ReadWrite and offline_access.", ru: "Добавьте адрес возврата ниже и делегированные разрешения Calendars.ReadWrite и offline_access." },
  "cal.steps.outlook.3": { en: "Create a client secret, paste it here with the application ID, then sign in.", ru: "Создайте секрет клиента, вставьте его сюда вместе с ID приложения и войдите." },
  "cal.steps.yandex.1": { en: "In your Yandex ID, open Security → App passwords and create one for Calendar (CalDAV).", ru: "В Яндекс ID откройте «Безопасность» → «Пароли приложений» и создайте пароль для Календаря (CalDAV)." },
  "cal.steps.yandex.2": { en: "Enter your Yandex login and that password below; your main password is never needed.", ru: "Укажите ниже логин Яндекса и этот пароль; основной пароль не нужен." },
  "cal.steps.icloud.1": { en: "At your Apple Account, open Sign-In and Security → App-Specific Passwords and create one.", ru: "В аккаунте Apple откройте «Вход и безопасность» → «Пароли приложений» и создайте пароль." },
  "cal.steps.icloud.2": { en: "Enter your Apple Account email and that password below.", ru: "Укажите ниже почту аккаунта Apple и этот пароль." },
  "cal.steps.caldav.1": { en: "Find your provider's CalDAV address (Fastmail, Nextcloud, Radicale and others publish it).", ru: "Найдите адрес CalDAV своего сервиса (его публикуют Fastmail, Nextcloud, Radicale и другие)." },
  "cal.steps.caldav.2": { en: "Enter it with your username and password; an app password is better where the service has one.", ru: "Укажите его с логином и паролем; если сервис даёт пароли приложений, лучше использовать такой." },
  "cal.steps.ics.1": { en: "Copy the calendar's public or secret address in iCal (.ics) format.", ru: "Скопируйте публичный или секретный адрес календаря в формате iCal (.ics)." },
